import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class InventoryMergerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Map<String, Integer> a = new HashMap<>();
        a.put("apple", 3);
        a.put("kiwi", 1);
        Map<String, Integer> b = new HashMap<>();
        b.put("apple", 2);
        b.put("pear", 5);
        try {
            TreeMap<String, Integer> merged = InventoryMerger.mergeInventories(a, b);
            check("merged size", 3, merged == null ? null : merged.size());
            check("shared item counts add", 5, merged == null ? null : merged.get("apple"));
            check("item only in a", 1, merged == null ? null : merged.get("kiwi"));
            check("item only in b", 5, merged == null ? null : merged.get("pear"));
            check("input a unchanged", 3, a.get("apple"));
            check("input b unchanged", 2, b.get("apple"));

            TreeMap<String, Integer> withEmpty = InventoryMerger.mergeInventories(a, new HashMap<>());
            check("merge with empty map keeps size", 2, withEmpty == null ? null : withEmpty.size());
            TreeMap<String, Integer> bothEmpty = InventoryMerger.mergeInventories(new HashMap<>(), new HashMap<>());
            check("two empty maps", 0, bothEmpty == null ? null : bothEmpty.size());
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

