import java.util.Map;
import java.util.TreeMap;

public class InventoryMerger {

    public static TreeMap<String, Integer> mergeInventories(Map<String, Integer> a, Map<String, Integer> b) {
        TreeMap<String, Integer> result = new TreeMap<>(a);
        for (Map.Entry<String, Integer> entry : b.entrySet()) {
            String item = entry.getKey();
            int count = entry.getValue();
            result.put(item, result.getOrDefault(item, 0) + count);
        }
        return result;
    }
}
